class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.gsl_func = CFUNCTYPE(c_double, c_double)(self._wrapper)

    def _wrapper(self, x):
        return self.func(x)

class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = gsl.gsl_integration_cquad_workspace_alloc(size)

    def free(self):
        gsl.gsl_integration_cquad_workspace_free(self.workspace)

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    global gsl
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    result = c_double(0)
    abserr = c_double(0)
    nevals = c_size_t(0)

    workspace = CQuadWorkspace(workspace_size)
    cquad_func = GSLFunction(func).gsl_func

    status = gsl.gsl_integration_cquad(cquad_func, a, b, epsabs, epsrel, byref(result), byref(abserr), byref(nevals), workspace.workspace)

    workspace.free()

    if status != 0:
        raise Exception(f"Integration failed with status {status}")

    return result.value, abserr.value, nevals.value

