class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)
        if not self.matrix:
            raise MemoryError("Failed to allocate GSL matrix")

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    gsl_matrix = GSLMatrix(rows, cols)
    np.ctypeslib.as_ctypes(np_array).data_as(ctypes.POINTER(ctypes.c_double))
    ctypes.memmove(gsl.gsl_matrix_ptr(gsl_matrix.matrix, 0, 0), np_array.ctypes.data, np_array.nbytes)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl.gsl_matrix_size1(gsl_matrix.matrix)
    cols = gsl.gsl_matrix_size2(gsl_matrix.matrix)
    np_array = np.empty((rows, cols), dtype=np.double)
    ctypes.memmove(np_array.ctypes.data, gsl.gsl_matrix_ptr(gsl_matrix.matrix, 0, 0), np_array.nbytes)
    return np_array

def gsl_multifit_covar(jacobian, epsrel):
    rows = jacobian.shape[0]
    covar = GSLMatrix(rows, rows)
    gsl.gsl_multifit_covar.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_void_p]
    gsl.gsl_multifit_covar.restype = ctypes.c_int
    result = gsl.gsl_multifit_covar(jacobian.matrix, epsrel, covar.matrix)
    if result != 0:
        raise RuntimeError("gsl_multifit_covar failed with error code %d" % result)
    return gsl_matrix_to_numpy(covar)

def compute_covariance_matrix(jacobian, epsrel, dim):
    if jacobian.shape[0] != dim or jacobian.shape[1] != dim:
        raise ValueError("Jacobian dimensions do not match specified dimension")
    jacobian_gsl = numpy_to_gsl_matrix(jacobian)
    return gsl_multifit_covar(jacobian_gsl, epsrel)

