def generate_signal(N):
    t = np.linspace(0, 2*np.pi, N, endpoint=False)
    signal = np.sin(t) + 0.1 * np.random.randn(N)
    outliers = np.random.choice(range(N), int(N*0.1), replace=False)
    signal[outliers] += 5 * np.random.randn(len(outliers))
    return signal

def apply_impulse_filter(signal, k, threshold_multiplier):
    N = len(signal)
    workspace = GSLFilterImpulseWorkspace(k)
    data = GSLVector(N)
    filtered_data = GSLVector(N)
    outliers = GSLVectorInt(N)

    for i in range(N):
        data.set(i, signal[i])

    gsl.gsl_filter_impulse_apply(workspace.workspace, data.vector, filtered_data.vector, outliers.vector, threshold_multiplier)

    result = []
    for i in range(N):
        result.append({
            'filtered_value': filtered_data.get(i),
            'median': gsl.gsl_stats_median_from_sorted_data(data.vector, 1, N),
            'sigma_bound': gsl.gsl_stats_sd_m_from_sorted_data(data.vector, 1, N) * threshold_multiplier,
            'is_outlier': bool(outliers.get(i))
        })

    workspace.free()
    data.free()
    filtered_data.free()
    outliers.free()

    return result

